const known=['pt','en','es'];let lang='pt';try{const requested=new URL(location.href).searchParams.get('lang'),saved=localStorage.getItem('pge-language');lang=known.includes(requested)?requested:known.includes(saved)?saved:'pt';localStorage.setItem('pge-language',lang);}catch(e){try{const requested=new URL(location.href).searchParams.get('lang');if(known.includes(requested))lang=requested;}catch(error){}}
