const nativeFetch=window.fetch.bind(window);window.fetch=(input,options)=>{if(lang==='pt')return nativeFetch(input,options);try{if(typeof input==='string'||input instanceof URL){const url=new URL(input,document.baseURI);if(url.origin===location.origin){if(/\/dados\/(planejamento|projetos|ideias-sociais|catalogo-conteudos|prestacao-contas|comunidades|agenda-solidaria)\.json$/.test(url.pathname))return nativeFetch(url.href,options);if(/\/dados\/[^/]+\.(json|txt)$/.test(url.pathname))url.pathname=url.pathname.replace(/\/dados\/([^/]+)$/,'/dados/'+lang+'/$1');else if(/\/catalogo\.txt$/.test(url.pathname))url.pathname=url.pathname.replace(/\/catalogo\.txt$/,'/dados/'+lang+'/catalogo.txt');return nativeFetch(url.href,options);}}}catch(e){}return nativeFetch(input,options);};
const dictionary=dictionaries[lang]||{},normalize=s=>String(s).replace(/\s+/g,' ').trim();
function translate(text){if(lang==='pt'||!text)return text;const key=normalize(text);let result=dictionary[key];if(result===undefined){result=key;for(const [pt,pair] of Object.entries(books)){const replacement=pair[lang==='en'?0:1];// Bible book names only when followed by a chapter number; personal names remain unchanged.
result=result.replace(new RegExp('\\b'+pt+'(?=\\s+\\d)','g'),replacement);}const prefixes=[['Tradução bíblica: ',lang==='en'?'Bible translation: ':'Traducción bíblica: '],['Saiba mais: ',lang==='en'?'Learn more: ':'Más información: '],['Uso do material: ',lang==='en'?'Resource use: ':'Uso del material: ']];for(const [pt,replacement] of prefixes)if(result.startsWith(pt))result=replacement+result.slice(pt.length);const parts=result.split(' · ');result=parts.map(part=>dictionary[part]||part).join(' · ');result=result.replace(/^Ler\s+/,lang==='en'?'Read ':'Leer ').replace(/ no contexto(?= ↗|$)/,lang==='en'?' in context':' en su contexto').replace(/(\d+) conteúdo\(s\)/g,lang==='en'?'$1 item(s)':'$1 contenido(s)').replace(/(\d+) material\(is\) encontrado\(s\)\./g,lang==='en'?'$1 resource(s) found.':'$1 material(es) encontrado(s).');if(result===key)return text;}
const leading=text.match(/^\s*/)[0],trailing=text.match(/\s*$/)[0];return leading+result+trailing;}
window.platformTranslate=translate;
function excluded(el){return !el||el.closest('script,style,textarea,input,[translate="no"],[data-source-original]');}
function freezeOptions(root){if(root.nodeType!==1&&root.nodeType!==9)return;const options=root.matches&&root.matches('option')?[root]:root.querySelectorAll('option');for(const option of options)if(!option.hasAttribute('value'))option.setAttribute('value',option.value);}
function translateElement(el){if(excluded(el))return;for(const attr of ['aria-label','title','placeholder','alt'])if(el.hasAttribute(attr)){const source=el.getAttribute(attr),value=translate(source);if(value!==source)el.setAttribute(attr,value);}if(el.hasAttribute('data-platform-section'))el.setAttribute('lang',window.platformLocaleTag);}
function walk(root){if(lang==='pt')return;if(root.nodeType===3){if(!excluded(root.parentElement)){const translated=translate(root.nodeValue);if(translated!==root.nodeValue)root.nodeValue=translated;}return;}if(root.nodeType!==1&&root.nodeType!==9)return;freezeOptions(root);if(root.nodeType===1)translateElement(root);for(const el of root.querySelectorAll('[aria-label],[title],[placeholder],[alt],[data-platform-section]'))translateElement(el);const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(excluded(node.parentElement))continue;const translated=translate(node.nodeValue);if(translated!==node.nodeValue)node.nodeValue=translated;}}
const pending=new Set();let queued=false;const observer=new MutationObserver(records=>{for(const record of records){if(record.type==='childList')for(const node of record.addedNodes)pending.add(node);else if(record.type==='characterData')pending.add(record.target);else if(record.type==='attributes')pending.add(record.target);}if(!queued){queued=true;queueMicrotask(()=>{queued=false;const nodes=[...pending];pending.clear();for(const node of nodes)if(node.isConnected)walk(node);});}});
if(lang!=='pt')observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','title','placeholder','alt']});
